mapper.select:
SELECT u.id, u.dept_id, u.username, u.nickname, u.email, u.phone, u.status, u.is_admin,
       u.last_login_time, u.create_time, d.name AS dept_name, d.path AS dept_path
FROM sys_user u
LEFT JOIN sys_dept d ON d.id = u.dept_id AND d.deleted = 0
WHERE u.deleted = 0

    AND u.username LIKE CONCAT('%', #{username}, '%') ESCAPE '\\'


    AND u.status = #{status}


    AND u.dept_id = #{deptId}


    AND (
        1 = 0

            OR u.id = #{scope.selfUserId}


            OR u.dept_id IN

                #{id}





                OR d.path = #{prefix} OR d.path LIKE CONCAT(#{prefix}, ',%')


    )

ORDER BY u.id DESC
